// CSD_RATIONALE_BEGIN
// Tracks a single parser-valid generated prefix. On each step it inspects how many
// grammar-valid next tokens are available: when the frontier is narrow it uses fully
// constrained decoding, and when it is wider it uses softly constrained decoding with
// a bias toward staying inside the grammar. This minimal state is enough to preserve
// parser validity while allowing the model to produce step-by-step math text with
// arithmetic segments delimited by << and >> whenever the grammar permits them.
// CSD_RATIONALE_END
generated := currentPrefix;
var current := currentPrefix;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant parser.IsValidPrefix(current)
  invariant generated == current
  invariant currentPrefix == current[..|currentPrefix|] || current == currentPrefix
  invariant helpers.cost <= steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(current) {
    break;
  } else {
    var count := helpers.ValidTokenCount(parser, current);
    if count <= 4 {
      var next := helpers.ConstrainedStep(lm, parser, prompt, current, eosToken);
      if next == eosToken {
        break;
      } else {
        current := current + [next];
        generated := current;
        steps := steps + 1;
      }
    } else {
      var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, current, 3.0, eosToken);
      if next == eosToken {
        break;
      } else {
        if isValid {
          current := current + [next];
          generated := current;
          steps := steps + 1;
        } else {
          var repaired := helpers.RollbackToValidPrefix(parser, current);
          current := repaired;
          generated := repaired;
        }
      }
    }
  }
}
cost := helpers.cost;

